mod solution;

fn main() {
    let cases = [
    (r#"abba; red blue blue red"#, r#"true"#),
    (r#"abba; red blue blue green"#, r#"false"#),
    (r#"
abba; red blue blue green
"#, r#"false"#),
    (r#"  
abba; red blue blue red
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS bidirectional-map");
}
